INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(153700, 0, 1537, 0, 0, 0, 'Ironforge', 'Ironforge is the ancient capital of the dwarves of Khaz Modan, carved deep into Ironforge Mountain above the snows of Dun Morogh. When the first dwarves came out of Uldaman, they raised an altar to the titan Khaz''goroth and built the Great Forge, and the city grew in rings of stone around that molten heart and took its name from it. From the High Seat beside the forge, King Magni Bronzebeard rules, though the senators of his court do not always welcome the reach of royal authority. The city has endured a great deal: the War of the Three Hammers, which drove the Wildhammer and Dark Iron clans from its gates, and the Horde siege of the Second War, which it held out against. Since the fall of Gnomeregan, the exiled gnomes of High Tinker Mekkatorque have made a home in Tinker Town, beside the Deeprun Tram their engineers designed to reach Stormwind. In the Hall of Explorers, the Explorers'' League seeks proof that the dwarves were made by the titans.', 'warcraft.wiki.gg/wiki/Ironforge (founding after leaving Uldaman, altar to Khaz''goroth and the Great Forge, city named for the forge, War of the Three Hammers, Second War siege held out, gnome refuge and Tinker Town, Deeprun Tram); warcraft.wiki.gg/wiki/Gelbin_Mekkatorque (Deeprun Tram schematics); quest 291 reward text (senator outraged at Magni''s authority); page_text 1759 (Uldaman reliefs, theory of creation by the titans)'),
(153701, 1, 1537, 1, 0, 0, 'The Forlorn Cavern', 'Beyond the Mystic Ward, a long, dim road winds around an underground lake: the Forlorn Cavern, the corner of Ironforge where honest dwarves seldom linger. Its darkness and seclusion suit those whose business does not bear the light of the forges. Rogues keep a hall here, a shady dealer lounges on its outer stair, and warlocks teach their art in the shop of Gerrig Bonegrip. Bonegrip himself collects old and dangerous lore, the kind said to open doorways and wake things that sleep, and will not even speak the names of the relics he seeks for fear of listening ears. Not all is sinister: a fishing master and his supplier work the cavern''s quiet waters.', 'warcraft.wiki.gg/wiki/Forlorn_Cavern (road around underground lake, between Mystic Ward and Hall of Explorers, shady deals, rogue and warlock trainers, Bonegrip''s shop, Traveling Fisherman); quest 971 description (Gerrig Bonegrip, lore that opens doorways and awakens Those Who Sleep; log text places him in the Forlorn Cavern); quest 735 description (will not speak their names, ears may be on us); DB spawns: Hulfdan Blackbeard, Fenthwick, Ormyr Flinteye rogue trainers; Tynnus Venomsprout <Shady Dealer>; Briarthorn, Thistleheart, Alexander Calder warlock trainers; Grimnur Stonebrand and Tansy Puddlefizz, all around map 45-53, 5-15'),
(153702, 2, 1537, 1, 1, 0, 'King Magni Bronzebeard', 'Magni Bronzebeard, eldest of three royal brothers, rules the dwarves of Khaz Modan from the High Seat beside the Great Forge. He held Ironforge through the Horde''s siege in the Second War, pledged his people to the Alliance that freed Khaz Modan, and turned dwarven industry toward archaeology, helping to found the Explorers'' League. Grief has followed him. When his brother Muradin was lost in Northrend, Magni poured his sorrow into forging the Ashbringer, and his daughter Moira was taken by the Dark Iron emperor Dagran Thaurissan. When the Scourge struck at the capitals, he vowed to drive its necropolises back to Northrend and follow, never doubting that Muradin lived.', 'warcraft.wiki.gg/wiki/Magni_Bronzebeard (eldest of three brothers, Siege of Ironforge, Alliance pledge, Explorers'' Guild, Ashbringer forged after Muradin''s believed death, Moira); quest 12771 description and reward text (eager to take the fight to Northrend, war priests, Muradin you must live); quests 4341, 4362, 4363; creature_template 2784 faction 55; warcraft.wiki.gg/wiki/A_Desperate_Alliance (12771 and 12809 belong to the 3.0.2 Scourge Invasion chain, later removed)'),
(153703, 2, 1537, 2, 1, 0, 'High Tinker Mekkatorque', 'Gelbin Mekkatorque first won fame in Gnomeregan as an inventor, and gnomish voters raised him to be High Tinker, leader of their people. He trusted his friend and chief advisor, Sicco Thermaplugg, and that trust undid them all. When troggs broke into Gnomeregan, a desperate measure Thermaplugg urged poisoned the city instead and killed most of its people, and Thermaplugg stayed behind to rule the ruins, a king of nothing. Mekkatorque led the survivors to Ironforge, where King Magni granted them refuge, and from Tinker Town he plans the day Gnomeregan will be retaken. When a Light-infused artifact from the naaru reached him amid the Scourge attacks, he dreamed at once of a device to turn dusk into dawn.', 'warcraft.wiki.gg/wiki/Gelbin_Mekkatorque (inventor, elected High Tinker, Thermaplugg chief advisor, trogg invasion, gas killed about eighty percent, refuge in Ironforge, Tinker Town); quest 2929 description (betrayal, king of nothing, we will retake Gnomeregan); quest 12809 description and reward text (Light-infused artifact, turn dusk into dawn); npc_text 15863; creature_template 7937 subname King of Gnomes, faction 64; warcraft.wiki.gg/wiki/A_Desperate_Alliance (Scourge Invasion origin of quest 12809)'),
(153704, 2, 1537, 3, 1, 0, 'Royal Historian Archesonus', 'Royal Historian Archesonus keeps the memory of Ironforge from his place in the royal chamber, a few steps from the king''s throne, and welcomes anyone who wishes to learn the history of the city. His favorite tale, and his most urgent, is that of the Dark Iron dwarves: the proud city of Thaurissan, the explosion that turned its green country into the Burning Steppes, and the nation that rose again from the ashes. His interest is not only scholarly. Dark Irons are surfacing more and more often, raising fortresses in the Badlands, digging in Uldaman and even striking at the dwarven dam on Loch Modan, and Archesonus seeks adventurers to learn what the ruins of Thaurissan still hide.', 'npc_text 2234, 2236, 2237, 2238, 2239 (gossip history of Thaurissan and recent Dark Iron activity); quest 3701 description; DB spawn: Archesonus 8879 at map 38.4,55.3, beside Magni 2784 at 39.1,56.2'),
(153705, 2, 1537, 4, 1, 0, 'High Explorer Magellas', 'High Explorer Magellas heads the Explorers'' League from the Hall of Explorers, home to the league''s library and a museum of wonders gathered across the world: an astrolabe crafted by the highborne of drowned Suramar, an unknown pteradon skeleton from Un''Goro Crater, a Horde catapult left from the Second War, and etched reliefs from Uldaman that tie the dwarves to the golem-like earthen. Proving that the dwarves were shaped by the titans is the league''s great ambition. When a miniature copy of the Discs of Norgannon was carried to him out of Uldaman, Magellas hailed it as perhaps the find of the century, and he now dreams of opening Uldum itself.', 'quest 2279 reward text (find of the century, enchanted creation); quests 2439, 2963 description, 2964 reward text (Uldum beckons); page_text 1756, 1757, 1759, 1761 (museum plaques in Ironforge); warcraft.wiki.gg/wiki/Explorers''_League (Hall of Explorers headquarters, Magellas heads the hall); creature_template 5387 subname Explorers'' League, faction 55'),
(153706, 2, 1537, 5, 1, 0, 'Historian Karnik', 'Historian Karnik tends the books of the Explorers'' League. With his friend Hammertoe Grez he searched for the lost artifacts of Uldaman, until the Shadowforge clan of the Dark Irons learned how much the two knew and Hammertoe was slain in the Badlands. Karnik set his mourning aside. With the backing of Advisor Belgrum, who spoke on the king''s authority, he struck at Angor Fortress, where Ambassador Infernus, sent by Ragnaros himself, oversaw the Shadowforge digs, and Belgrum then saw Hammertoe''s dream fulfilled by recovering the Tablet of Will, a titan shard said to give created beings a will of their own. Lately Karnik''s studies have turned to the riddles of Uldum and the elven ruins of Azshara.', 'quests 723, 724 (Hammertoe''s death, Karnik his partner in seeking Uldaman''s artifacts); quests 725, 726, 762 (Belgrum, king''s authority, Angor Fortress, Ambassador Infernus sent by Ragnaros); quest 1139 description and reward text (Tablet of Will); quests 2946, 2977, 3448; creature_text 2916 (Ragnaros? Terrible news indeed); creature_template 2909 Hammertoe Grez'),
(153707, 2, 1537, 6, 1, 0, 'Prospector Stormpike', 'Prospector Stormpike works in the Explorers'' League headquarters in the Hall of Explorers, a hot-tempered dwarf who cannot abide trivial matters or slow progress. Yet scholars as far off as Southshore send him their puzzles, for there may be no one north of Blackrock Spire better at breaking ciphers and untangling enchanted script. He keeps a close eye on the league''s digs, from Prospector Ironband''s excavation in Loch Modan, whose missing shipment of blastpowder enraged him, to Uldaman, lost to a sudden tide of troggs. When his friend Baelog and a small band of dwarves were cut off deep inside that dig, Stormpike sent for help to find them.', 'quest 301 description and reward text (hotheaded, Ironband''s blastpowder); quest 302; quest 514 description (no one north of Blackrock Spire who can read this); quest 554 description and reward text (master of decryption, ensorcelled parchment); quest 2398 description (Uldaman lost to troggs, Baelog); quest 707'),
(153708, 2, 1537, 7, 1, 0, 'Tinkmaster Overspark', 'Tinkmaster Overspark calls himself the chief architect of modern gnomish engineering, and from Tinker Town he guards the bold principles of that craft so that gnomish invention may keep shining brighter than any other. The fall of Gnomeregan cost him dearly. His creation Techbot, once a kindly helper full of gizmos and knowledge, was jolted by a stray spark as the city fell; its positronic brain turned negatronic, reversing its nature, and it now roams the ruined halls in a frenzy. Overspark longs to recover its memory core and set it right. He also mentions, almost in passing, that he would welcome any good schematic for eliminating radiation.', 'npc_text 2137 (chief architect, arclight spanners, schematic for radiation elimination); quest 2922 description and reward text (Techbot); quest 2923 description (Techbot once kind and helpful); creature_template 7944 subname Gnomish Engineering Trainer, faction 64'),
(153709, 2, 1537, 8, 1, 0, 'Talvash del Kissel', 'Talvash del Kissel was once a jeweler of great renown in Ironforge, until a rival spread word that one of his necklaces had cursed its owner. The paladin who wore it had gone into Uldaman to cleanse its evil taint and never returned, and no one wants to buy trinkets from a maker of cursed goods. Now the gnome scrapes by in a small house in the city, greeting strangers with nervous denials about fee collection and summonses. Bring him the shattered necklace and its scattered gems and he will restore it gladly, so long as the world hears that Talvash del Kissel does not make cursed jewelry.', 'quests 2198, 2199, 2200, 2204 (descriptions and reward texts); quest 2948 reward text (unjustly in a hole); npc_text 2253 (fee collection and/or a summons); creature_text 6826 (spell focus inside my home)'),
(153710, 3, 1537, 1, 1, 0, 'A King''s Tribute', 'Among the soldiers lost in the Thandol Span tragedy was a dwarf named Sully Balloo. He was found pinned beneath the icy waters, and his last letter, written with painstaking care and addressed to his wife Sara in Ironforge, survived waterlogged and torn. Its delivery broke her heart. Too stricken to stand before the throne herself, Sara sent a plea to King Magni. The king, who feels the loss of every dwarf who falls for the Alliance, could not bring Sully back, but he could honor him. He commissioned a memorial from Grand Mason Marblesten, who would work only with the finest stone: Alterac granite from Darrow Hill in Hillsbrad, quarried from war-torn Lordaeron. The finished memorial now stands in Ironforge, so that those who come after may remember for whom such soldiers gave their lives.', 'quest 637 description and reward text (waterlogged letter, pinned beneath the icy waters); quest 683 description; quest 686 description (Magni, every dwarf that fights for the Alliance, commission to Marblesten); quest 689 description (Thandol Span tragedy, Alterac Granite from Darrow Hill in Hillsbrad); quest 700 description and reward text; creature_text 2695, 2784, 2790; gameobject 139852 Memorial to Sully Balloo spawned in Ironforge'),
(153711, 3, 1537, 2, 1, 0, 'The Ruin of Thaurissan', 'Royal Historian Archesonus tells the history of the Dark Iron dwarves to any who will listen. Hundreds of years ago, while the dwarven nation was torn by civil war, the Dark Iron capital of Thaurissan stood proudly in a lush land then part of the Redridge Mountains. One day a colossal explosion consumed it, leaving the city in ruin and the country around it the ashen waste now called the Burning Steppes. How it happened, the historian admits, no one knows. The survivors withdrew into the mountain and rebuilt; from the ashes rose Blackrock Spire, a new Dark Iron nation, fortifications in the Cauldron of the Searing Gorge, and rumors of an ancient evil ruling the kingdom. Now the Dark Irons are stirring again, and Archesonus sends the willing into the smoldering ruins to gather what the old relics can reveal, past the assassins who guard them.', 'npc_text 2236, 2237, 2238, 2239 (Archesonus gossip history); quest 3702 description; quest 3701 description and reward text (relics, Thaurissan guardians)'),
(153712, 3, 1537, 3, 1, 0, 'The Princess and the Emperor', 'Moira Bronzebeard, King Magni''s daughter, vanished in the Burning Steppes while in the care of a dwarf named Kharan Mighthammer. The king''s men turned the Steppes upside down and found a single clue: she might be held in Blackrock Depths, where Kharan himself was said to be a prisoner. The news Kharan gave made Magni slam his fist down in anger. Emperor Dagran Thaurissan, the king''s old adversary, held Moira under a spell, and with her the kingdom itself. Magni''s command was plain: slay the emperor to break the enchantment, and do the princess no harm. Yet when Thaurissan fell, Moira wept over him, called him great and honorable, and declared that the heir to Ironforge would be a Dark Iron dwarf, whether her father approved or not. Magni could only conclude that even in death, Thaurissan had won.', 'quest 4341 description; quest 4361 reward text (fist slammed down); quest 4362 description and reward text; quest 4363 description and reward text; warcraft.wiki.gg/wiki/Magni_Bronzebeard (Moira''s abduction)'),
(153713, 3, 1537, 4, 1, 0, 'The Exiles of Gnomeregan', 'In Tinker Town the gnomes of Gnomeregan live as exiles, and nearly every one of them carries a piece of the catastrophe. High Tinker Mekkatorque trusted Mekgineer Thermaplugg, who betrayed him and all gnomekind and now rules the ruined city; the High Tinker wants the betrayer dead as the first step toward taking Gnomeregan back. Master Mechanic Castpipe frets over the vital data left behind in the flight and organizes missions to pull it from the city''s high security terminals. Tinkmaster Overspark grieves for his creation Techbot, turned against its makers, and Klockmort Spannerspan needs the essential artificials no one remembered to save. Gnoarn, bald since the radiation leak and furious at the troggs, directs scouts and an underground assault crew from central command in Ironforge.', 'quest 2929 description and reward text; quests 2930, 2931 descriptions; quest 2922 description; quest 2924 description; quest 2927 description and reward text (Gnoarn''s hair, radiation leak, troggs); quests 2039, 2041 descriptions (Bingles reconnaissance, Shoni''s underground assault crew, central command); creature_queststarter: 7937 starts 2929, 7950 starts 2930, 7944 starts 2922, 6169 starts 2924, 6569 starts 2927, 2039, 2041'),
(153714, 3, 1537, 5, 1, 0, 'Secrets of the Creators', 'The Explorers'' League has long suspected that the dwarves were not born but made, shaped by the titans like the earthen of old. Uldaman in the Badlands lies at the heart of that search, though the dig was lost when troggs poured in faster than dwarven might could stop them. Fearing for his friend Baelog and a band trapped inside, Prospector Stormpike sent help to find them, and Baelog''s journal led to the sealed Chamber of Khaz''mul. Deeper in, the Discs of Norgannon yielded a miniature copy of themselves, and High Explorer Magellas declared it the find of the century. Historian Karnik went further: the discs might unlock Uldum in the Tanaris desert. At its sealed gates a Stone Watcher stirred, but warned that the key was incomplete without the Plates of Uldum, and the league is now searching its records for where they might lie.', 'quest 2398 description and reward text; quest 2240 description and reward text (Chamber of Khaz''mul); quest 2279 description and reward text; quests 2439, 2963 description and reward text; quests 2946, 2977 reward texts (Stone Watcher, Plates of Uldum); quest 2964; page_text 1759 (earthen and dwarves)');
